'use strict';
const assert=require('node:assert/strict'),m=require('./spotify-preview.js');
let s=m.initial();
assert.equal(m.reduce(s,'toggle').playing,false);
assert.equal(m.reduce(s,'seek',9999).position,m.tracks[0].duration);
assert.equal(m.reduce(s,'seek',-4).position,0);
assert.equal(m.reduce(s,'next').index,1);
assert.equal(m.reduce(s,'previous').index,2);
assert.deepEqual(m.reduce(s,'save').saved,[0]);
assert.deepEqual(m.reduce(m.reduce(s,'save'),'save').saved,[]);
assert.equal(m.reduce(s,'repeat').repeat,'all');
assert.equal(m.reduce(m.reduce(s,'repeat'),'repeat').repeat,'one');
assert.equal(m.reduce(s,'mode','echo').mode,'wifi');
assert.equal(m.reduce(s,'mode','pc').playing,false);
assert.equal(m.reduce(s,'device','bad').device,s.device);
assert.equal(m.reduce(s,'device','iPhone (sample)').device,'iPhone (sample)');
assert.equal(m.reduce(s,'tick').position,103);
assert.equal(m.reduce({...s,position:225,repeat:'one'},'tick').position,0);
assert.equal(m.reduce({...s,index:2,position:257},'tick').playing,false);
assert.equal(m.time(226),'3:46');
console.log('17 Spotify preview state assertions passed');
